script:
frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {
        override_item_search(frm);
    }
});

function override_item_search(frm) {
    frm.set_query("item_code", "items", function() {
        return {
            query: "vansale.sf_trading.custom_search.item_search_sorted",
            filters: {}
        };
    });
}

frappe.ui.form.on("Purchase Invoice", {
    before_workflow_action: function(frm) {
        if (frm.selected_workflow_action === "Reject") {
            return new Promise((resolve, reject) => {
                let submitted = false;

                let d = new frappe.ui.Dialog({
                    title: "Rejection Reason",
                    fields: [{
                        fieldname: "reason",
                        fieldtype: "Small Text",
                        label: "Reason for Rejection",
                        reqd: 1
                    }],
                    primary_action_label: "Reject",
                    primary_action(values) {
                        if (!values.reason) return;
                        submitted = true;
                        frm._rejection_reason = values.reason;
                        d.hide();
                        resolve();
                    }
                });

                d.show();

                setTimeout(() => {
                    d.$wrapper.css("z-index", "9999");
                    d.$wrapper.find(".modal-dialog").css("z-index", "10000");
                    d.$wrapper.find("textarea").css({
                        "pointer-events": "auto",
                        "position": "relative",
                        "z-index": "10001"
                    }).focus();
                    $(".modal-backdrop").css("z-index", "9998");
                }, 400);

                d.$wrapper.on("hidden.bs.modal", function() {
                    if (!submitted) reject("cancelled");
                });

            }).catch(e => {
                if (e !== "cancelled") console.error(e);
            });
        }
    },

    after_workflow_action: function(frm) {
        if (frm.doc.workflow_state === "Rejected" && frm._rejection_reason) {

            let reason = frm._rejection_reason;
            let owner = frm.doc.owner;

            frappe.db.get_value("User", owner, "full_name", (r) => {
                let fullname = r.full_name || owner;
                let comment_text = `@${fullname} — Rejected: ${reason}`;

                // Step 1: Auto-post comment
                frappe.call({
                    method: "frappe.client.insert",
                    args: {
                        doc: {
                            doctype: "Comment",
                            comment_type: "Comment",
                            reference_doctype: frm.doc.doctype,
                            reference_name: frm.doc.name,
                            content: comment_text,
                            comment_by: frappe.session.user
                        }
                    },
                    callback: function() {
                        frm._rejection_reason = null;

                        // Step 2: Reload doc
                        frm.reload_doc().then(() => {
                            setTimeout(() => {

                                // Step 3: Click collapsed input to expand
                                let possible_inputs = [
                                    ".form-comments .comment-input-wrapper input",
                                    ".form-comments .comment-input-wrapper [contenteditable]",
                                    ".form-comments .frappe-comment-box",
                                    ".form-comments .comment-box",
                                    ".form-comments p[data-placeholder]"
                                ];

                                possible_inputs.forEach(sel => {
                                    let el = document.querySelector(sel);
                                    if (el) {
                                        el.click();
                                        $(el).trigger("click").trigger("focus");
                                    }
                                });

                                // Step 4: Fill the expanded editor
                                setTimeout(() => {
                                    let editor =
                                        document.querySelector(".form-comments .ql-editor") ||
                                        document.querySelector(".comment-box .ql-editor") ||
                                        document.querySelector("[data-placeholder='Type a reply / comment']") ||
                                        document.querySelector(".form-comments [contenteditable='true']");

                                    if (editor) {
                                        editor.innerHTML = `<p>${comment_text}</p>`;
                                        editor.dispatchEvent(new Event("input", { bubbles: true }));
                                        editor.dispatchEvent(new Event("keyup", { bubbles: true }));
                                        editor.focus();

                                        // Move cursor to end
                                        let range = document.createRange();
                                        let sel = window.getSelection();
                                        range.selectNodeContents(editor);
                                        range.collapse(false);
                                        sel.removeAllRanges();
                                        sel.addRange(range);

                                        console.log("✅ Comment box filled successfully");
                                    } else {
                                        // Debug: show what's available
                                        console.log("❌ Editor not found. Available:", 
                                            document.querySelectorAll(".form-comments *")
                                        );
                                    }
                                }, 1000);

                            }, 2000);
                        });
                    }
                });
            });
        }
    }
});
